INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (109, 353, 'PE pallet wrapping film- hand use and machine use', '../upload/image/20181227/20181227131644_31088.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;font-size:16px;">PE Stretch Film for pallets package</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Blown PE Stretch Film for pallets pallet package, it characteristics excellent anti-piercing and stretching ability. Lightweight, strong tenacity, excellent puncture resistance, good self-adhesion</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Thickness: 15 – 20UM ( Microns) for hand-warp , 15-25 UM ( Microns) for machine-warp</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Width: 50-750MM</span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Grade: hand use, semi-automatic machine use, auto-machine use </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;">Color: natural color(clear), black, blue, red, ivory-white </span></p> <p><span style="color:#009900;font-family:Verdana;font-size:16px;"><img alt="" src="../upload/image/20181227/20181227131730_61064.jpg"/><img alt="" src="../upload/image/20181227/20181227131748_27619.jpg"/></span></p>', '2026-09-06 20:58:45');